const recordAggregationFailureQualitySnapshot = `-- name: RecordAggregationFailureQualitySnapshot :one
WITH quality_failure_lock AS MATERIALIZED (
  SELECT pg_advisory_xact_lock(1129270869, 5)
),
previous_snapshot AS MATERIALIZED (
  SELECT
    snapshot.id,
    snapshot.incomplete_stays,
    snapshot.overdue_planned_departures,
    snapshot.silent_accommodations,
    snapshot.aggregation_failures,
    snapshot.suspected_duplicates,
    snapshot.suspected_duplicates_reason,
    snapshot.fnrh_failures,
    snapshot.fnrh_failures_reason
  FROM quality_failure_lock
  LEFT JOIN LATERAL (
    SELECT candidate.id, candidate.window_code, candidate.updated_at, candidate.incomplete_stays, candidate.overdue_planned_departures, candidate.silent_accommodations, candidate.aggregation_failures, candidate.suspected_duplicates, candidate.suspected_duplicates_reason, candidate.fnrh_failures, candidate.fnrh_failures_reason
    FROM analytics.quality_snapshots AS candidate
    WHERE candidate.window_code = 'last_30_days'
    ORDER BY candidate.updated_at DESC, candidate.id DESC
    LIMIT 1
  ) AS snapshot ON true
),
inserted_snapshot AS (
  INSERT INTO analytics.quality_snapshots (
    id,
    window_code,
    updated_at,
    incomplete_stays,
    overdue_planned_departures,
    silent_accommodations,
    aggregation_failures,
    suspected_duplicates,
    suspected_duplicates_reason,
    fnrh_failures,
    fnrh_failures_reason
  )
  SELECT
    $1::uuid,
    'last_30_days',
    $2::timestamptz,
    coalesce(previous.incomplete_stays, 0),
    coalesce(previous.overdue_planned_departures, 0),
    coalesce(previous.silent_accommodations, 0),
    coalesce(previous.aggregation_failures, 0) + 1,
    previous.suspected_duplicates,
    coalesce(
      previous.suspected_duplicates_reason,
      'pseudonym_not_approved'
    ),
    previous.fnrh_failures,
    coalesce(previous.fnrh_failures_reason, 'not_implemented')
  FROM previous_snapshot AS previous
  RETURNING id, aggregation_failures
),
copied_coverage AS (
  INSERT INTO analytics.quality_coverage (
    quality_snapshot_id,
    category_code,
    status,
    ratio
  )
  SELECT
    inserted.id,
    coverage.category_code,
    coverage.status,
    coverage.ratio
  FROM inserted_snapshot AS inserted
  JOIN previous_snapshot AS previous ON true
  JOIN analytics.quality_coverage AS coverage
    ON coverage.quality_snapshot_id = previous.id
  RETURNING quality_snapshot_id
)
SELECT
  inserted.id,
  inserted.aggregation_failures,
  count(copied.quality_snapshot_id)::integer AS coverage_count
FROM inserted_snapshot AS inserted
LEFT JOIN copied_coverage AS copied ON true
GROUP BY inserted.id, inserted.aggregation_failures
`

type RecordAggregationFailureQualitySnapshotParams struct {
	SnapshotID pgtype.UUID        `json:"snapshot_id"`
	UpdatedAt  pgtype.Timestamptz `json:"updated_at"`
}

type RecordAggregationFailureQualitySnapshotRow struct {
	ID                  pgtype.UUID `json:"id"`
	AggregationFailures int32       `json:"aggregation_failures"`
	CoverageCount       int32       `json:"coverage_count"`
}

func (q *Queries) RecordAggregationFailureQualitySnapshot(ctx context.Context, arg RecordAggregationFailureQualitySnapshotParams) (RecordAggregationFailureQualitySnapshotRow, error) {
	row := q.db.QueryRow(ctx, recordAggregationFailureQualitySnapshot, arg.SnapshotID, arg.UpdatedAt)
	var i RecordAggregationFailureQualitySnapshotRow
	err := row.Scan(&i.ID, &i.AggregationFailures, &i.CoverageCount)
	return i, err
}

const upsertPresenceDay = `-- name: UpsertPresenceDay :execrows
INSERT INTO analytics.presence_days (
  stay_id,
  visitor_id,
  presence_on,
  kind,
  weight,
  source_stay_version,
  as_of_on,
  updated_at
)
VALUES (
  $1,
  $2,
  $3,
  $4,
  $5,
  $6,
  $7,
  $8
)
ON CONFLICT (stay_id, visitor_id, presence_on)
DO UPDATE SET
  kind = EXCLUDED.kind,
  weight = EXCLUDED.weight,
  source_stay_version = EXCLUDED.source_stay_version,
  as_of_on = EXCLUDED.as_of_on,
  updated_at = EXCLUDED.updated_at
WHERE analytics.presence_days.source_stay_version <= EXCLUDED.source_stay_version
  AND (
    analytics.presence_days.kind,
    analytics.presence_days.weight,
    analytics.presence_days.source_stay_version,
    analytics.presence_days.as_of_on
  ) IS DISTINCT FROM (
    EXCLUDED.kind,
    EXCLUDED.weight,
    EXCLUDED.source_stay_version,
    EXCLUDED.as_of_on
  )
`

type UpsertPresenceDayParams struct {
	StayID            pgtype.UUID        `json:"stay_id"`
	VisitorID         pgtype.UUID        `json:"visitor_id"`
	PresenceOn        pgtype.Date        `json:"presence_on"`
	Kind              string             `json:"kind"`
	Weight            pgtype.Numeric     `json:"weight"`
	SourceStayVersion int64              `json:"source_stay_version"`
	AsOfOn            pgtype.Date        `json:"as_of_on"`
	UpdatedAt         pgtype.Timestamptz `json:"updated_at"`
}

func (q *Queries) UpsertPresenceDay(ctx context.Context, arg UpsertPresenceDayParams) (int64, error) {
	result, err := q.db.Exec(ctx, upsertPresenceDay,
		arg.StayID,
		arg.VisitorID,
		arg.PresenceOn,
		arg.Kind,
		arg.Weight,
		arg.SourceStayVersion,
		arg.AsOfOn,
		arg.UpdatedAt,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}
